INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-01037', 'accessible-bathroom-and-grab-bar', '1', '2026-11-13 22:28', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:28', 'session_2026-11-13-edmonton-checklist-pass', 'Item 8.6 states the accessible washroom stall (minimum 1700 mm x 1500 mm, toilet height 400 to 460 mm, grab bars, an outward-swinging door); item 8.5 sink, mirror and dispenser heights.');
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-01037', 'luminance-contrast-and-pattern', '1', '2026-11-13 22:28', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:28', 'session_2026-11-13-edmonton-checklist-pass', 'The source requires colour contrast at many elements (items 1.2, 2.10, 4.1, 4.7, 5.1, 5.5, 6.4, 7.2, 9.8, 11.2) and states no luminance or reflectance figure for it.');
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-01037', 'reach-range-and-accessible-controls', '1', '2026-11-13 22:28', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:28', 'session_2026-11-13-edmonton-checklist-pass', 'Items 2.8, 5.4, 9.1, 9.3, 9.4 and 9.5 state mounting heights for door buttons, elevator controls, phones, a drinking fountain, a counter and light switches.');
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-01037', 'stair-ramp-threshold-biomechanics-accessibility', '4', '2026-11-13 22:28', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:28', 'session_2026-11-13-edmonton-checklist-pass', 'Item 6.1 states ramp slopes (1 in 20, a preferred maximum of 1 in 16, 1 in 12 attributed to the Alberta building code) and item 6.2 a 9 m landing interval; item 2.9 a 13 mm threshold rise; item 4.3 stair rise and run.');
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-01037', 'threshold-door-hardware', '1', '2026-11-13 22:28', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:28', 'session_2026-11-13-edmonton-checklist-pass', 'Item 2.3 states doorway clearance (850 mm, 920 mm preferred), 2.4 lever handles, 2.8 an automatic door operator button height, 2.9 a 13 mm threshold rise.');
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-103', 'SW', 'P3', 'OPEN', NULL, NULL, 'log-search demands a subject (--slug, --parameter or --mined-ref-id) even for --origin owner-supplied, where no search ran. The owner-supplied admission of REF-01037 (search_executions exec_id 204) carries --slug stair-ramp-threshold-biomechanics-accessibility only to satisfy the writer, and its findings note says so. Writer defect found by the first digest run and standing in the replay; a tooling pull request (rule 10).', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-104', 'SW', 'P3', 'OPEN', NULL, NULL, 'log-mining cannot record a deferred forward (cited-by) direction once a backward pass has set evidence_sources.citation_mining_status to mined: the writer refuses, "That column is ONE flag for BOTH directions (GAP-015/GAP-022, unruled)". REF-01037 has its backward pass logged and its forward deferral (a municipal grey PDF has no citation index) unrecorded. Writer defect; a tooling pull request (rule 10).', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-105', 'SW', 'P2', 'OPEN', NULL, NULL, 'The engine (scripts/assess/assess_cell.py) writes into a pending cell''s gap text "from N source(s)", and on the first digest run''s scratch database N disagreed with the number of distinct sources holding in-lens extractions (ADJUDICATION F11: the parameter 4 ALL lens held figures from six sources while the sentence said one). The sentence counts something other than sources in lens. Tool defect: not patched in a research batch (rule 10); a tooling pull request reads the count site. Until then, read in-lens sources with: select count(distinct e.ref_id) from source_value_extractions e join v_live_lens_links l using(extraction_id) where e.parameter_id=<P> and <lens column>=<code>.', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-106', 'SW', 'P3', 'OPEN', NULL, NULL, 'No sanctioned writer holds evidence_sources.pub_year_note: add-source has no flag for it, amend-source refuses it ("not an amendable judgement field"), and correct-source takes only payload-backed fields and refuses a DOI-less source. REF-01037 stores pub_year 2022 with no basis. The basis to record: 2022 is the PDF''s own CreationDate (D:20220324091437-06''00'', read with PyMuPDF from retrieval-log/session_2026-11-13-edmonton-checklist-pass/1a117aff4c5947a8.pdf), the build date of this file, not a printed publication date (none is printed); the page-1 self-link carries cb=1631580961, which decodes to 2021-09-14, an earlier fetch of the same URL. Writer gap; a tooling pull request (rule 10), then the note is written through the new verb.', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-107', 'SW', 'P3', 'OPEN', NULL, NULL, 'raise-follow-up accepts only two reasons (absence-needs-tested-value, read-outside-admitting-purpose), so an extraction whose printed figure is ambiguous has no follow-up to carry it. REF-01037 item 5.3 prints "optimal turning radius of 1500x1500mm" (radius, diameter or the side of a square); its extraction on parameter 5 (select extraction_id from source_value_extractions where ref_id=''REF-01037'' and parameter_id=5 and figure_role=''claim'') stores the side, 1500, with the ambiguity in notes only; --value-as-written was refused because the quote writes the number as a numeral, which is right. Writer gap.', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, 5, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-108', 'EG', 'P2', 'OPEN', NULL, NULL, 'R7 harm statements in REF-01037 tied to no parameter, each held as an observation (DEFERRED) and flagged on the owner-supplied search (exec_id 204, harm_finding raised): item 1.5 "The more painted surface, the more likely pavement will become slippery" (slip, parking-stall paint); item 4.5 "a contrasting colour on the back of the stairwell above the tactile strips to alert a potential safety hazard" (open area beneath stairs, a head-strike and cane-detection hazard); item 8.2 "so persons who are blind do not become disoriented" (washroom entrance geometry). No parameter holds slip resistance, under-stair enclosure or entrance turns; a judgment row waits on a parameter (AQ-4) or element handling (AQ-7).', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-109', 'DEC', 'P2', 'OPEN', NULL, NULL, 'AQ-1 (ADJUDICATION 5.3, OPEN): what lens a figure carries when its clause names no person, function or need. REF-01037 figures whose clause names no one were NOT written in this replay (OD-31 forbids ALL as an identity; D-0182 needs at least one lens; the lens writer needs words that warrant a code). Each is parked as the exact db.py add-extraction argv, lens blank, waits_on AQ-1, with its relation edges, in scratchpad/session_2026-11-13-edmonton-checklist-pass/parked-writes.jsonl (count them: wc -l on that file). Replay through the writer once AQ-1 is answered (rule 10; ADJUDICATION Q10, AQ-8 reading a).', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-110', 'EG', 'P2', 'OPEN', NULL, NULL, 'Accessibility direction for parameters 5 (turning circle) and 9 (door width) is not set (select parameter_id from base_parameters where accessibility_direction is null). REF-01037 page 1 states which way is better for both ("a wider turning radius and wider doors are required by many wheelchairs and scooters today"), held as harm findings with insufficient edges. Whether a grey committee''s assertion sets a direction (set-parameter-direction --ref-id) is the judging session''s call, deliberately not made in this replay and to be named in the pull request (ADJUDICATION F3).', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-111', 'EG', 'P2', 'OPEN', NULL, NULL, 'R4: REF-01037 phrases adjudicated DEFERRED, with no reader yet (ADJUDICATION R4, P3: T-079 v_deferred_acts gains an adjudication arm). Each rationale names what it waits on: AQ-4 (a quantity with no parameter), AQ-7 (an element or feature), OR-17 (colour contrast against TERM-011, genuinely unsettled), AQ-6 (the two "barrier-free path of travel" phrases, items 1.2 and 2.1, not adjudicated to TERM-048 and not minted). Derive the list: with latest as (select a.* from term_adjudications a where a.adjudication_id=(select max(adjudication_id) from term_adjudications b where b.observation_id=a.observation_id)) select o.observation_id, o.surface_form, o.locator, substr(l.rationale,1,60) from observed_terms o join latest l using(observation_id) where o.ref_id=''REF-01037'' and l.outcome=''DEFERRED''. Counts by outcome: with latest as (select a.* from term_adjudications a where a.adjudication_id=(select max(adjudication_id) from term_adjudications b where b.observation_id=a.observation_id)) select coalesce(l.outcome,''UNADJUDICATED''), count(*) from observed_terms o left join latest l using(observation_id) where o.ref_id=''REF-01037'' group by 1.', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-112', 'EG', 'P3', 'OPEN', NULL, NULL, 'REF-01037 is a City of Edmonton document and its figures are recorded under country code CA: base_jurisdictions holds no sub-national code for Alberta or Edmonton (T-024 built the registry; add-jurisdiction admits one with an approval reference).', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'CA', NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-113', 'RP', 'P2', 'OPEN', NULL, NULL, 'Backward-mining leads named by REF-01037 and staged REFERENCE-ONLY, not retrieved: the Safety Codes Council Barrier-Free Design Guide (Aug 2019 PDF), the City of Edmonton Access Design Guide, Policy C602, and the Alberta Building Code (no edition stated). The Alberta code is the presumed root of every figure the source marks Code (required) (OR-19; those rows are root_type untraced); T-071 step 3 re-roots them when it is admitted. Derive the leads: select ref_id, title from source_locators where recovered_from like ''REF-01037%''.', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:32', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
