INSERT INTO "source_scans" ("scan_id", "ref_id", "mode", "catalogue_version", "target_parameter_id", "text_scope", "pages_read", "pages_total", "file_sha256", "open_pass_done", "method", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (19, 'REF-01037', 'catalogue', 12, NULL, 'full', 9, 9, '6e725b0be41f32d13870faf7ec538d19527d83593ecf12d1e7d39ffc48e9fd30', 1, 'full-read', 'Replay of the digest (second run). The derived full text (nine of nine pages, each page-marked) was read in full against every active parameter and lens before this scan was recorded. Open pass done before this record: every one of the numbered checklist items (derived from scratchpad/session_2026-11-13-edmonton-checklist-pass/items.json) and every figure the text states carries at least one observation with its sentence verbatim, and every observation is adjudicated (NAMES-EXISTING only to a term that is a parameter or already declined; DEFERRED otherwise, with the open question it waits on). The per-run colour class (blue = the source''s Code (required), magenta = its Best Practice) is the text-layer colour in items.json, checked against the page renders by the first run and by the adjudicator; the renders were not re-read in this replay.', '2026-11-13 22:29', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:29', 'session_2026-11-13-edmonton-checklist-pass');
