INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (95, 103, 'DEFERRED', NULL, 'An element or feature the source requires, with no figure. The catalogue holds no parameter for it; adjudicating it to a held term that is neither a parameter nor declined would fail R16, and declining such a term in a single-source batch is the owner''s open question AQ-7 (ADJUDICATION 5.3). Deferred; the phrase is kept as printed. The catalogue holds TERM-027 (accessible parking), which is neither a parameter nor declined; not adjudicated to it here.', '2026-11-13 22:28', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:28', 'session_2026-11-13-edmonton-checklist-pass');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (96, 104, 'DEFERRED', NULL, 'OT-1 and OT-2 (references/project-standards.md, ''OT-1: "Barrier-free path of travel. It is a circulation route that is specific to people in wheelchairs/mobility devices."'') place the owner''s term as a circulation route through a building, specific to wheelchair and mobility-device users, to be minted from observation 68. This source uses the phrase for the exterior route from parking or drop-off to the entrance, with a colour-contrast provision attached. Whether this sighting names that term is the owner''s open question AQ-6. Not adjudicated to TERM-048 and the term is not minted here.', '2026-11-13 22:28', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:28', 'session_2026-11-13-edmonton-checklist-pass');
