INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (98, 106, 'DEFERRED', NULL, 'The source requires colour contrast and states no figure. Whether its colour contrast names the catalogue''s TERM-011 LRV contrast (a light reflectance value difference) is a vocabulary judgment under OR-17 that this source alone does not settle (ADJUDICATION F8): the genuinely unsettled kind of DEFERRED.', '2026-11-13 22:28', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:28', 'session_2026-11-13-edmonton-checklist-pass');
